            , TH_ENG_PLAN_INFO          B
            , SY_FP_DAILY_NET_DEMAND_H  C
        WHERE  A.MASTER_ID = @v_master_id
        AND    A.PLAN_ID = @v_plan_id
        AND    A.MASTER_ID = B.MASTER_ID
        AND    A.PLAN_ID = B.PLAN_ID 
        AND    A.DUE_DATE < B.PLAN_START_DTTM
        AND    A.MASTER_ID = C.INSTANCE_ID
        AND    A.PLAN_ID = C.DPP_PLAN_ID 
        AND    A.DEMAND_ID = C.FP_DEMAND_ID                
        UNION  ALL
        SELECT
              C.INSTANCE_ID           
            , C.DPP_PLAN_ID AS FP_PLAN_ID            
            , C.COMPANY_ID            
            , C.DIVISION_ID           
            , C.SITE_ID               
            , C.FP_DEMAND_ID AS DEMAND_ID             
