        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null


        SET @v_table_name = 'TH_BUF_SCM_PROBLEM_REPORT'

        UPDATE TH_BUF_SCM_PROBLEM_REPORT
        SET    TH_BUF_SCM_PROBLEM_REPORT.PROBLEM_FACTORY      = '-'
             , TH_BUF_SCM_PROBLEM_REPORT.PROBLEM_LINE         = '-'
             , TH_BUF_SCM_PROBLEM_REPORT.PROBLEM_OPERATION    = '-'
             , TH_BUF_SCM_PROBLEM_REPORT.PROBLEM_DESCRIPTION  = B.PROBLEM_DESCR
             , TH_BUF_SCM_PROBLEM_REPORT.PROBLEM_REASON       ='No producing link'
        FROM   TH_BUF_SCM_PROBLEM_REPORT A,
               (
                SELECT *
                FROM   (
                        SELECT A.*,
                               B.PROBLEM_DATA, B.PROBLEM_LIST, REFERENCE_TABLE, B.PROBLEM_DESCRIPTION as PROBLEM_DESCR,
                               ROW_NUMBER() OVER ( PARTITION BY A.DEMAND_ID ORDER BY B.CHECK_SEQ, B.PROBLEM_SEQ, B.PROBLEM_DATA) SEQ
                        FROM   TH_BUF_SCM_PROBLEM_REPORT A,
                               SY_FP_MASTER_VALIDATION_H B
                        WHERE  A.INSTANCE_ID = @v_master_id
                        AND    A.FP_PLAN_ID = @v_plan_id
                        AND    A.PROBLEM_TYPE = 'UNPLAN'
                        AND    B.PLAN_DATE = @v_plan_date
                        AND    A.COMPANY_ID = B.COMPANY_ID
                        AND    A.DIVISION_ID = B.DIVISION_ID
                        AND    A.SITE_ID = B.SITE_ID
                        AND    A.ITEM_ID = B.TOP_ITEM_ID
                        AND    A.INSTANCE_ID = B.INSTANCE_ID
