        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null


        UPDATE TH_BUF_SCM_PROBLEM_REPORT
        SET    TH_BUF_SCM_PROBLEM_REPORT.PROBLEM_FACTORY     = B.P_FACTORY_ID
             --, TH_BUF_SCM_PROBLEM_REPORT.PROBLEM_OPERATION   = B.P_OPERATION_ID
             , TH_BUF_SCM_PROBLEM_REPORT.PROBLEM_DESCRIPTION = ' ITEM ''' + CASE WHEN CHARINDEX('_LANE', P_ITEM_ID) = 0 THEN P_ITEM_ID
                                                                                 ELSE SUBSTRING(P_ITEM_ID, 1, CHARINDEX('_LANE', P_ITEM_ID) - 1)
                                                                            END + N''' 이 ''' 
                                                                          + CASE WHEN CHARINDEX('^', B.P_FACTORY_ID) = 0 THEN B.P_FACTORY_ID 
                                                                                 ELSE SUBSTRING(B.P_FACTORY_ID, 1, CHARINDEX('^', B.P_FACTORY_ID)-1)
                                                                            END  + '''  FACTORY, '''
                                                                          + B.P_LINE_ID + ''' LINE, ''' 
                                                                          + A.PROBLEM_OPERATION + N''' OPERATION 에서 CAPA 가 부족합니다.'
        FROM   TH_BUF_SCM_PROBLEM_REPORT A,
               (
                SELECT A.*,
                       SUBSTRING(PROBLEM_DESCRIPTION, INDEX1, INDEX2 - INDEX1 - 2) AS P_ITEM_ID
                     , SUBSTRING(PROBLEM_DESCRIPTION, INDEX2, INDEX3 - INDEX2 - 2) AS P_FACTORY_ID
                     , SUBSTRING(PROBLEM_DESCRIPTION, INDEX3, INDEX4 - INDEX3 - 2) AS P_LINE_ID
                     , SUBSTRING(PROBLEM_DESCRIPTION, INDEX4, 999)  AS P_OPERATION_ID
                FROM   (
                        SELECT A.*,
                               CASE WHEN CHARINDEX('::', PROBLEM_DESCRIPTION) > 0 THEN CHARINDEX('::', PROBLEM_DESCRIPTION)+2
                                    ELSE 1
                               END  AS INDEX1,
                               CHARINDEX('##', PROBLEM_DESCRIPTION)+2 INDEX2,
                               CHARINDEX('##', PROBLEM_DESCRIPTION, CHARINDEX('##', PROBLEM_DESCRIPTION)+1)+2 INDEX3,
                               CHARINDEX('##', PROBLEM_DESCRIPTION, CHARINDEX('##', PROBLEM_DESCRIPTION, CHARINDEX('##', PROBLEM_DESCRIPTION)+1)+1)+2 INDEX4
                        FROM   TH_BUF_SCM_PROBLEM_REPORT A
                        WHERE  INSTANCE_ID = @v_master_id
                        AND    FP_PLAN_ID = @v_plan_id
                        --AND    PROBLEM_TYPE = 'UNPLAN'
                        AND    PROBLEM_LINE   <> 'VIRTUAL_LANE'
                        AND    PROBLEM_REASON IN ('CAPACITY_SHORT','Capacity short')
                        AND    PROBLEM_DESCRIPTION LIKE '%##%'
                       ) A
                WHERE  INDEX1 < INDEX2
                AND    INDEX2 < INDEX3
                AND    INDEX3 < INDEX4
               ) B
        WHERE  A.INSTANCE_ID = B.INSTANCE_ID
        AND    A.FP_PLAN_ID = B.FP_PLAN_ID
        AND    A.DEMAND_ID = B.DEMAND_ID

        --LOG 생성
        SET @n_cnt = @@ROWCOUNT

        --LOG 생성
        SET @v_message = 'UPDATE COUNT : ' + CONVERT(nvarchar, @n_cnt)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null


        UPDATE TH_BUF_SCM_PROBLEM_REPORT
        SET    TH_BUF_SCM_PROBLEM_REPORT.PROBLEM_FACTORY     = B.P_FACTORY_ID
             , TH_BUF_SCM_PROBLEM_REPORT.PROBLEM_REASON      = 'Capacity short'
             , TH_BUF_SCM_PROBLEM_REPORT.PROBLEM_DESCRIPTION = ' ITEM ''' + CASE WHEN CHARINDEX('_LANE', P_ITEM_ID) = 0 THEN P_ITEM_ID
                                                                                 ELSE SUBSTRING(P_ITEM_ID, 1, CHARINDEX('_LANE', P_ITEM_ID) - 1)
                                                                            END + N''' 이 ''' 
                                                                          + CASE WHEN CHARINDEX('^', B.P_FACTORY_ID) = 0 THEN B.P_FACTORY_ID 
                                                                                 ELSE SUBSTRING(B.P_FACTORY_ID, 1, CHARINDEX('^', B.P_FACTORY_ID)-1)
                                                                            END  + '''  FACTORY, '''
                                                                          + B.P_LINE_ID + ''' LINE, ''' 
                                                                          + A.PROBLEM_OPERATION + N''' OPERATION 에서 CAPA 가 부족합니다.'
        FROM   TH_BUF_SCM_PROBLEM_REPORT A,
               (
                SELECT A.*,
                       SUBSTRING(PROBLEM_DESCRIPTION, INDEX1, INDEX2 - INDEX1 - 2) AS P_ITEM_ID
                     , SUBSTRING(PROBLEM_DESCRIPTION, INDEX2, INDEX3 - INDEX2 - 2) AS P_FACTORY_ID
                     , SUBSTRING(PROBLEM_DESCRIPTION, INDEX3, INDEX4 - INDEX3 - 2) AS P_LINE_ID
                     , SUBSTRING(PROBLEM_DESCRIPTION, INDEX4, 999)  AS P_OPERATION_ID
                FROM   (
                        SELECT A.*,
                               CASE WHEN CHARINDEX('::', PROBLEM_DESCRIPTION) > 0 THEN CHARINDEX('::', PROBLEM_DESCRIPTION)+3 
                                    ELSE 2
                               END  AS INDEX1,
                               CHARINDEX('##', PROBLEM_DESCRIPTION)+2 INDEX2,
                               CHARINDEX('##', PROBLEM_DESCRIPTION, CHARINDEX('##', PROBLEM_DESCRIPTION)+1)+2 INDEX3,
                               CHARINDEX('##', PROBLEM_DESCRIPTION, CHARINDEX('##', PROBLEM_DESCRIPTION, CHARINDEX('##', PROBLEM_DESCRIPTION)+1)+1)+2 INDEX4
                        FROM   TH_BUF_SCM_PROBLEM_REPORT A,
                               TH_ENG_ITEM B
                        WHERE  A.INSTANCE_ID  = @v_master_id
                        AND    A.FP_PLAN_ID   = @v_plan_id
                        AND    A.PROBLEM_TYPE = 'LATE'
                        AND    A.PROBLEM_LINE <> 'VIRTUAL_LANE'
                        AND    A.PROBLEM_REASON IN ('MATERIAL_SHORT','Material short')
                        AND    A.PROBLEM_DESCRIPTION LIKE '%##%'
                        AND    A.PROBLEM_DESCRIPTION LIKE '*%ALT_STOCK_altitem*'
                        AND    A.INSTANCE_ID  = B.MASTER_ID
                        AND    A.FP_PLAN_ID   = B.PLAN_ID
                        AND    A.PROBLEM_DESCRIPTION LIKE '%' + B.ITEM_ID + '%altitem*'
                        AND    B.ITEM_TYPE    = 'R'
                       ) A
                WHERE  INDEX1 < INDEX2
                AND    INDEX2 < INDEX3
                AND    INDEX3 < INDEX4
               ) B
        WHERE  A.INSTANCE_ID = B.INSTANCE_ID
        AND    A.FP_PLAN_ID = B.FP_PLAN_ID
        AND    A.DEMAND_ID = B.DEMAND_ID

        --LOG 생성
        SET @n_cnt = @@ROWCOUNT

        --LOG 생성
        SET @v_message = 'UPDATE COUNT : ' + CONVERT(nvarchar, @n_cnt)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null

        UPDATE TH_BUF_SCM_PROBLEM_REPORT
        SET    TH_BUF_SCM_PROBLEM_REPORT.PROBLEM_FACTORY     = '-'
             , TH_BUF_SCM_PROBLEM_REPORT.PROBLEM_LINE        = '-'
             , TH_BUF_SCM_PROBLEM_REPORT.PROBLEM_REASON      = 'Material short'
             , TH_BUF_SCM_PROBLEM_REPORT.PROBLEM_DESCRIPTION = ' ITEM ''' + CASE WHEN CHARINDEX('_LANE', P_ITEM_ID) = 0 THEN P_ITEM_ID
                                                                                 ELSE SUBSTRING(P_ITEM_ID, 1, CHARINDEX('_LANE', P_ITEM_ID) - 1)
                                                                            END + N''' 의 ''' 
                                                                          + A.PROBLEM_OPERATION + N''' OPERATION 에 등록된 재고가 부족합니다.'
        FROM   TH_BUF_SCM_PROBLEM_REPORT A,
               (
                SELECT A.*,
                       SUBSTRING(PROBLEM_DESCRIPTION, INDEX1, INDEX2 - INDEX1 - 2) AS P_ITEM_ID
                     , SUBSTRING(PROBLEM_DESCRIPTION, INDEX2, INDEX3 - INDEX2 - 2) AS P_FACTORY_ID
                     , SUBSTRING(PROBLEM_DESCRIPTION, INDEX3, INDEX4 - INDEX3 - 2) AS P_LINE_ID
                     , SUBSTRING(PROBLEM_DESCRIPTION, INDEX4, 999)  AS P_OPERATION_ID
                FROM   (
                        SELECT A.*,
                               CASE WHEN CHARINDEX('::', PROBLEM_DESCRIPTION) > 0 THEN CHARINDEX('::', PROBLEM_DESCRIPTION)+2
                                    ELSE 1
                               END  AS INDEX1,
                               CHARINDEX('##', PROBLEM_DESCRIPTION)+2 INDEX2,
                               CHARINDEX('##', PROBLEM_DESCRIPTION, CHARINDEX('##', PROBLEM_DESCRIPTION)+1)+2 INDEX3,
                               CHARINDEX('##', PROBLEM_DESCRIPTION, CHARINDEX('##', PROBLEM_DESCRIPTION, CHARINDEX('##', PROBLEM_DESCRIPTION)+1)+1)+2 INDEX4
                        FROM   TH_BUF_SCM_PROBLEM_REPORT A
                        WHERE  INSTANCE_ID = @v_master_id
                        AND    FP_PLAN_ID  = @v_plan_id
                        --AND    PROBLEM_TYPE = 'UNPLAN'
                        AND    PROBLEM_REASON IN ('CAPACITY_SHORT','Capacity short')
                        AND    PROBLEM_DESCRIPTION LIKE '%##%'
                        AND    PROBLEM_LINE = 'VIRTUAL_LANE'
                       ) A
                WHERE  INDEX1 < INDEX2
                AND    INDEX2 < INDEX3
                AND    INDEX3 < INDEX4
               ) B
        WHERE  A.INSTANCE_ID = B.INSTANCE_ID
        AND    A.FP_PLAN_ID = B.FP_PLAN_ID
        AND    A.DEMAND_ID = B.DEMAND_ID

        --LOG 생성
        SET @n_cnt = @@ROWCOUNT

        --LOG 생성
        SET @v_message = 'UPDATE COUNT : ' + CONVERT(nvarchar, @n_cnt)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null

        
        ------------------------------------------------------------------------------------------------------------------------------------
        
        SET @v_table_name = 'FP_PROBLEM_REPORT_R'

        DELETE FROM SY_FP_PROBLEM_REPORT_R
        WHERE INSTANCE_ID = @v_master_id
        AND    FP_PLAN_ID = @v_plan_id;
      
        INSERT INTO SY_FP_PROBLEM_REPORT_R 
             (
                INSTANCE_ID           
              , FP_PLAN_ID            
              , COMPANY_ID            
              , DIVISION_ID           
              , SITE_ID               
              , DEMAND_ID             
              , PROBLEM_SEQ           
              , SCP_TARGET_ID         
              , ITEM_ID               
              , DUE_DATE              
              , DUE_FENCE_DATE        
              , RESPONSE_TIME         
              , PROBLEM_TYPE          
              , PROBLEM_REASON        
              , PROBLEM_QTY           
              , PROBLEM_ITEM          
              , PROBLEM_PLANT         
              , PROBLEM_FACTORY       
              , PROBLEM_OPERATION     
              , PROBLEM_LINE          
              , PROBLEM_DESCRIPTION   
              , EPST                  
              , LPST                  
              , INSERT_ID
              , INSERT_TIME
           )
        SELECT
                INSTANCE_ID           
              , FP_PLAN_ID            
              , COMPANY_ID            
              , DIVISION_ID           
              , SITE_ID               
              , DEMAND_ID             
              , ROW_NUMBER() OVER( ORDER BY DEMAND_ID) AS PROBLEM_SEQ           
              , SCP_TARGET_ID         
              , ITEM_ID               
              , DUE_DATE              
              , DUE_FENCE_DATE        
              , RESPONSE_TIME         
              , PROBLEM_TYPE          
              , UPPER(PROBLEM_REASON) AS PROBLEM_REASON        
              , PROBLEM_QTY           
              , PROBLEM_ITEM          
              , PROBLEM_PLANT         
              , PROBLEM_FACTORY       
              , PROBLEM_OPERATION     
              , PROBLEM_LINE          
              , PROBLEM_DESCRIPTION   
              , EPST                  
              , LPST                  
              , @v_proc_name AS insert_id
              , sysdatetime() AS insert_dttm
        FROM   (
                SELECT
                        INSTANCE_ID           
                      , FP_PLAN_ID            
                      , COMPANY_ID            
                      , DIVISION_ID           
                      , SITE_ID               
                      , DEMAND_ID             
                      , 0 PROBLEM_SEQ           
                      , SCP_TARGET_ID         
                      , ITEM_ID               
                      , DUE_DATE              
                      , DUE_FENCE_DATE        
                      , RESPONSE_TIME         
                      , PROBLEM_TYPE          
                      , PROBLEM_REASON
                      , PROBLEM_QTY           
                      , PROBLEM_ITEM          
                      , PROBLEM_PLANT         
                      , CASE WHEN CHARINDEX('^', PROBLEM_FACTORY) = 0 THEN PROBLEM_FACTORY 
                             ELSE SUBSTRING(PROBLEM_FACTORY, 1, CHARINDEX('^', PROBLEM_FACTORY)-1) 
                        END  AS PROBLEM_FACTORY
                      , PROBLEM_OPERATION     
                      , CASE WHEN CHARINDEX('^', PROBLEM_LINE) = 0 THEN PROBLEM_LINE 
                             ELSE SUBSTRING(PROBLEM_LINE, 1, CHARINDEX('^', PROBLEM_LINE)-1) 
                        END  AS PROBLEM_LINE
                      , PROBLEM_DESCRIPTION   
                      , EPST                  
                      , LPST                  
                FROM    TH_BUF_SCM_PROBLEM_REPORT A
                WHERE   INSTANCE_ID = @v_master_id
                AND     FP_PLAN_ID = @v_plan_id
                --AND     PROBLEM_TYPE = 'UNPLAN'
                UNION  ALL
                 SELECT DISTINCT
                        A.INSTANCE_ID           
                      , A.DPP_PLAN_ID AS FP_PLAN_ID            
                      , A.COMPANY_ID            
                      , A.DIVISION_ID           
                      , A.SITE_ID               
                      , A.FP_DEMAND_ID AS DEMAND_ID             
                      , 0 PROBLEM_SEQ           
                      , A.SCP_TARGET_ID         
                      , A.ITEM_ID               
                      , A.DUE_DATE              
                      , A.DUE_FENCE_DATE        
                      , E.START_TIME RESPONSE_TIME
                      , CASE WHEN A.MFG_WEEK = D.WEEK THEN 'NORMAL' 
                             WHEN A.MFG_WEEK > D.WEEK THEN 'PRECEDING'
                             WHEN A.MFG_WEEK < D.WEEK THEN 'LATE'
                        END  PROBLEM_TYPE      
                      , CASE WHEN A.MFG_WEEK = D.WEEK THEN 'NORMAL' 
                             WHEN A.MFG_WEEK > D.WEEK THEN 'PRECEDING'
                             WHEN A.MFG_WEEK < D.WEEK THEN 'LATE'
                        END  PROBLEM_REASON      
                      , A.MFG_QTY       AS PROBLEM_QTY           
                      , A.ITEM_ID       AS PROBLEM_ITEM          
                      , A.PLANT_ID      AS PROBLEM_PLANT         
                      , E.SITE_ID       AS PROBLEM_FACTORY       
                      , E.OPERATION_ID  AS PROBLEM_OPERATION     
                      , E.ROUTE_ID      AS PROBLEM_LINE          
                      , 'MFG_WEEK (' + A.MFG_WEEK + ') : PLAN WEEK (' + D.WEEK + ') = '
                        + CASE WHEN A.MFG_WEEK = D.WEEK THEN 'NORMAL' 
                               WHEN A.MFG_WEEK > D.WEEK THEN 'PRECEDING'
                               WHEN A.MFG_WEEK < D.WEEK THEN 'LATE'
                          END  
                        AS PROBLEM_DESCRIPTION   
                      , E.EPST                  
                      , E.LPST                        
                 FROM  SY_FP_DAILY_NET_DEMAND_H A
                       INNER HASH JOIN TH_BUF_OUT_ITEM_PEGGING B
                             ON     A.INSTANCE_ID = B.MASTER_ID
                             AND    A.DPP_PLAN_ID = B.PLAN_ID
                             AND    A.DPP_PLAN_ID = B.OUT_VERSION_ID
                             AND    A.FP_DEMAND_ID = B.DEMAND_ID
                             AND    B.DEMAND_ID IS NOT NULL
                       INNER HASH JOIN TH_BUF_OUT_ITEM_PLAN C
                             ON     A.INSTANCE_ID = C.MASTER_ID
                             AND    A.DPP_PLAN_ID = C.PLAN_ID
                             AND    A.DPP_PLAN_ID = C.OUT_VERSION_ID
                             AND    B.IN_ITEM_PEGGING_ID = C.ITEM_PEGGING_ID
                       INNER HASH JOIN SY_SCM_SYS_CALENDAR_M D
                             ON     D.DATE_ID = CONVERT(date, dbo.fn_set_work_date2(C.master_id, C.plan_id, C.EVENT_TIME, C.EVENT_TIME), 112)
                       INNER HASH JOIN TH_BUF_OUT_ORDER_TRACKING E
                             ON     A.INSTANCE_ID = E.MASTER_ID
                             AND    A.DPP_PLAN_ID = E.PLAN_ID
                             AND    A.DPP_PLAN_ID = E.OUT_VERSION_ID
                             AND    C.WORK_ORDER_ID = E.ORDER_ID
                 WHERE  A.INSTANCE_ID = @v_master_id
                 AND    A.DPP_PLAN_ID = @v_plan_id
                 AND    NOT EXISTS (
                                    SELECT 1
                                    FROM   TH_BUF_SCM_PROBLEM_REPORT X
                                    WHERE  X.INSTANCE_ID = A.INSTANCE_ID
                                    AND    X.FP_PLAN_ID = A.DPP_PLAN_ID
                                    AND    X.DEMAND_ID = A.FP_DEMAND_ID 
                                   )
               ) A
        
        --LOG 생성
        SET @n_cnt = @@ROWCOUNT

        --LOG 생성
        SET @v_message = 'INSERT COUNT : ' + CONVERT(nvarchar, @n_cnt)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null
                        
      END
      
      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, null, 'END', 999999, null, '=============== End of procedure ===============', null
    END TRY

    BEGIN CATCH
      BEGIN

        DECLARE 
          @v_error_message nvarchar(max),
          @v_error_procedure nvarchar(max),
          @v_error_line nvarchar(max)

          SET @v_error_message = ERROR_MESSAGE()

          SET @v_error_procedure = ERROR_PROCEDURE()

          SET @v_error_line = convert(nvarchar,ERROR_LINE())


          EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_error_procedure, null, 'ERROR', null, @v_error_line, null, @v_error_message

          IF @@TRANCOUNT > 0
               COMMIT WORK 
      END
    END CATCH
END
